// Holt Laufnummer und Token aus der Adresse (Seite) oder aus dem Body (Absenden).
// Prüft nur die Form, ob sie stimmen, prüft "Zugang und Eingaben prüfen".
const absenden = $('Entscheidung abgesendet').isExecuted;
const r = $input.first().json;
const q = (absenden ? r.body : r.query) || {};
const lauf_id = String(q.lauf ?? '').trim();
const token = String(q.t ?? '').trim();
const formOk = /^bc3-[a-z0-9-]{1,40}$/.test(lauf_id) && /^[0-9a-f]{64}$/.test(token);

return [{ json: {
  art: absenden ? 'entscheidung' : 'seite',
  lauf_id: formOk ? lauf_id : '',
  token: formOk ? token : '',
  fehler: formOk ? null : 'link unvollständig',
  eingabe: absenden ? q : null,
} }];

// Prüft Token, Frist und ob schon entschieden ist, beim Absenden auch die Eingaben.
// Baut die Antwort für BC3-80 mit denselben Feldnamen wie das frühere Formular.
// weg: seite | entscheidung | fehler (für "Wie weiter?")
const a = $('Anfrage prüfen').first().json;
const z = $input.first().json || {};
const FRIST_TAGE = 7;

const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
function fehler(status, meldung) {
  const html = '<!doctype html><html lang="de"><head><meta charset="utf-8">'
    + '<meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex">'
    + '<title>BC3 · Gate 2</title></head><body style="font-family:Segoe UI,Arial,sans-serif;'
    + 'background:#f4f6f9;color:#1f2933;margin:0"><div style="background:#1F3A5F;color:#fff;padding:12px 20px">'
    + '<b>BC3 · Gate 2</b></div><p style="max-width:640px;margin:24px auto;padding:0 16px">'
    + esc(meldung) + '</p></body></html>';
  return [{ json: {
    weg: 'fehler', status, meldung,
    inhalt: a.art === 'seite' ? html : JSON.stringify({ ok: false, meldung }),
    inhaltstyp: a.art === 'seite' ? 'text/html; charset=utf-8' : 'application/json; charset=utf-8',
  } }];
}

if (a.fehler) return fehler(400, a.fehler);
if (!z.lauf_id || z.token !== a.token) {
  return fehler(403, 'link ungültig');
}
const frist = new Date(new Date(z.angelegt_am).getTime() + FRIST_TAGE * 864e5);
const daten = typeof z.daten === 'string' ? JSON.parse(z.daten) : z.daten;
// Seit 22.10.2026 (Expertenrunde Gate 2): nach der Entscheidung bis zur Frist lesbar,
// mit der Entscheidung aus freigaben oben. Absenden bleibt gesperrt.
if (z.entschieden_am) {
  if (a.art !== 'seite') return fehler(409, 'schon entschieden');
  if (!(frist > new Date())) return fehler(410, 'frist abgelaufen, die Entscheidung steht in der Tabelle freigaben');
  return [{ json: { weg: 'seite', lauf_id: z.lauf_id, daten, frist: frist.toISOString(), entschieden: {
    zeitpunkt: z.f_zeitpunkt || z.entschieden_am, entscheidung: z.f_entscheidung || null,
    person: z.f_person || null, begruendung: z.f_begruendung || null } } }];
}
if (!(frist > new Date())) {
  return fehler(410, 'frist abgelaufen, der Lauf gilt als abgelehnt');
}
if (a.art === 'seite') {
  return [{ json: { weg: 'seite', lauf_id: z.lauf_id, daten, frist: frist.toISOString() } }];
}

// Absenden: Werte nur aus festen Listen, Texte gekürzt
const KRITERIEN = 'Die Akzeptanzkriterien — siehst du das auch so?';
const AUFSICHT = 'Die menschliche Aufsicht — siehst du das auch so?';
const KRIT_WAHL = ['Ja, das sehe ich auch so', 'Nein, ein anderes ist schwächer',
  'Nein, die Kriterien sind in Ordnung', 'Das kann ich hier nicht beurteilen'];
const AUFS_WAHL = ['Ja, das sehe ich auch so', 'Nein, ich sehe es anders', 'Betrifft diese Lieferung nicht'];
const ENTSCHEIDUNG = { frei: 'Freigeben', nach: 'Zurück zur Nachbesserung', ab: 'Ablehnen' };

const e = a.eingabe || {};
const text = (v, max) => String(v ?? '').trim().slice(0, max);
const wahl = text(e.entscheidung, 10);
const kriterien = text(e.kriterien, 100);
const aufsicht = text(e.aufsicht, 100);
const begruendung = text(e.begruendung, 4000);
const person = text(e.person, 80);
const hochrisiko = !!(daten && daten.hochrisiko);

const f = [];
if (!ENTSCHEIDUNG[wahl]) f.push('Bitte eine Entscheidung wählen.');
if (['nach', 'ab'].includes(wahl) && !begruendung) f.push('Bei Nachbessern und Ablehnen ist die Begründung Pflicht.');
if (!person) f.push('Bitte angeben, wer entscheidet.');
if (!KRIT_WAHL.includes(kriterien)) f.push('Bitte zu den Akzeptanzkriterien Stellung nehmen.');
if (aufsicht && !AUFS_WAHL.includes(aufsicht)) f.push('Die Antwort zur Aufsicht ist unbekannt.');
if (hochrisiko && !aufsicht) f.push('Bitte zur menschlichen Aufsicht Stellung nehmen.');
if (f.length) return fehler(422, f.join(' '));

return [{ json: {
  weg: 'entscheidung',
  lauf_id: z.lauf_id,
  entscheidung: ENTSCHEIDUNG[wahl],
  antwort: {
    [KRITERIEN]: kriterien,
    ...(aufsicht ? { [AUFSICHT]: aufsicht } : {}),
    'Deine Entscheidung': ENTSCHEIDUNG[wahl],
    'Deine Anmerkung': begruendung,
    'Wer gibt frei': person,
  },
} }];

// Setzt die Daten des Laufs in die Seite ein. Vorlage: gate2-seite\n8n\seite.html im Ablageordner.
// "<" wird im JSON maskiert, damit kein Text aus der Lieferung den Skriptblock beenden kann.
const z = $input.first().json;
const daten = JSON.stringify({ lauf: z.daten, frist: z.frist, entschieden: z.entschieden || null }).replace(/</g, '\\u003c');

const SEITE = `<!doctype html>
<html lang="de">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
