<div class="topbar">
  <b>BC3 · Gate 2</b><span class="sub">Lieferung an BC4 freigeben</span>
  <span class="sub" id="frist" style="margin-left:auto"></span>
</div>
<div id="testband" class="testband" hidden>
  TESTLAUF: „Freigeben“ legt keinen Pull Request im Gruppen-Repository an.
</div>
<div class="rahmen"><nav id="navi"></nav><main id="seite"></main></div>
<script id="daten" type="application/json">__DATEN__</script>
<script>
const DATEN = JSON.parse(document.getElementById('daten').textContent);
const ZUGANG = new URLSearchParams(location.search);
const esc = s => String(s ?? '').replace(/[&<>"]/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const KRIT_WAHL = ['Ja, das sehe ich auch so', 'Nein, ein anderes ist schwächer',
  'Nein, die Kriterien sind in Ordnung', 'Das kann ich hier nicht beurteilen'];
const AUFS_WAHL = ['Ja, das sehe ich auch so', 'Nein, ich sehe es anders', 'Betrifft diese Lieferung nicht'];
const ENTSCHEIDUNG = {
  frei: { text: 'Freigeben', wert: 'freigegeben', klasse: 'frei' },
  nach: { text: 'Zurück zur Nachbesserung', wert: 'nachbessern', klasse: 'nach' },
  ab: { text: 'Ablehnen', wert: 'abgelehnt', klasse: 'ab' },
};
let L, Z;

function zeigen() {
  L = DATEN.lauf;
  Z = { kriterien: null, aufsicht: null, entscheidung: null, begruendung: '', person: '', fertig: null, sendet: false };
  document.getElementById('testband').hidden = L.liefermodus === 'echt';
  if (DATEN.frist) document.getElementById('frist').textContent = 'Frist: '
    + new Date(DATEN.frist).toLocaleString('de-DE', { dateStyle: 'short', timeStyle: 'short' });
  window.onhashchange = () => { merken(); zeichnen(); window.scrollTo(0, 0); };
  zeichnen();
}

// Seit 22.10.2026 (Expertenrunde Gate 2): gegliedert wie ein Lieferschein.
// Worum es geht → was offen ist → 1 was reinkam → 2 was im Lauf passiert ist →
// 3 was herauskam → 4 was rausgeht → dein Urteil und deine Entscheidung.
// Nach der Entscheidung bleibt die Seite bis zur Frist lesbar (DATEN.entschieden).
const SCHRITTE = ['BC3-10', 'BC3-15', 'BC3-20', 'BC3-30', 'BC3-40', 'BC3-50', 'BC3-70', 'Gate 2', 'BC3-80'];
const ADRESSAT = { bc4: 'an BC4', organisation: 'an die Organisation', plattform: 'an die Plattform',
  bc2: 'an BC2', bc3: 'an BC3', bc2_und_bc4: 'an BC2 und BC4' };
const GATE1 = { approved: 'freigegeben', pending: 'noch offen', rejected: 'abgelehnt' };
const ENTSCHIEDEN = { freigegeben: 'Freigegeben', nachbessern: 'Zurück zur Nachbesserung', abgelehnt: 'Abgelehnt' };
const zeit = v => v ? new Date(v).toLocaleString('de-DE', { dateStyle: 'short', timeStyle: 'short' }) : '–';

function zeichnen() {
  const stories = L.epics.reduce((n, e) => n + e.stories.length, 0);
  const E = DATEN.entschieden;
  const ein = L.eingang || {}, aus = L.ausgang || {};
  // Seit 23.10.2026: jeder Bereich sammelt seine Abschnitte, die Seitenleiste zeigt einen davon
  const B = {};
  let s;
  const bereich = k => { s = B[k] = []; };

  // Seit 22.10.2026 (Svetlana): fehlende Messverfahren sind kein offener Punkt, sondern ein Hinweis
  // zur Weitergabe. Sie kommen so von BC2, BC3 gibt sie unverändert weiter und vermerkt sie in den
  // offenen Punkten. An BC2 geht das noch nicht, einen Rückweg gibt es nicht (of-17, 23.10.2026). Ältere Läufe führen sie noch als offenen Punkt, der fällt hier heraus.
  const alleKrit = L.epics.flatMap(e => e.stories.flatMap(st => st.kriterien.map(k => ({ ...k, story: st.titel }))));
  const ohneMess = L.epics.flatMap(e => e.stories).filter(st => st.kriterien.some(k => fehltMess(k.messverfahren)));
  const nurMess = g => g.id === 'akzeptanzkriterien' && ohneMess.length && !/ohne Kriterium/i.test(g.beleg || '');
  const offen = L.geprueft.filter(g => !g.ok && !nurMess(g)), ok = L.geprueft.filter(g => g.ok);
  const messKarte = () => {
    const mit = alleKrit.find(k => !fehltMess(k.messverfahren)), ohne = alleKrit.find(k => fehltMess(k.messverfahren));
    return \`<div class="karte hinweiskarte"><b>Hinweis zur Weitergabe: \${ohneMess.length} von \${stories} Stories sagen nicht, woran man erkennt, dass sie erfüllt sind</b>
      <div>Zu jedem Akzeptanzkriterium gehört ein Messverfahren: wie man prüft, ob es erfüllt ist. Bei diesen Stories fehlt es,
        weil das Konzept von BC2 keins nennt. BC3 erfindet keins.</div>
      \${mit && ohne ? \`<div class="beispiel"><div><span class="ok-text">Mit Messverfahren:</span> „\${esc(mit.text)}“<br><span class="klein">Geprüft wird so: \${esc(mit.messverfahren)}</span></div>
        <div><span class="offen-mess">Ohne:</span> „\${esc(ohne.text)}“<br><span class="klein">Wie man das prüft, steht nirgends.</span></div></div>\` : ''}
      <div class="hilft"><b>Was heißt das für dich?</b> Nichts, du musst deswegen weder nachbessern noch begründen.
        BC3 gibt die Stories so weiter, wie BC2 sie geliefert hat, und vermerkt die Lücke in den offenen Punkten. An BC2 geht sie noch nicht, dafür gibt es noch keinen Weg.
        BC4 kann sie bauen, aber später nicht nachweisen, dass sie erfüllt sind.</div>
      <details><summary>Betroffene Stories (\${ohneMess.length})</summary><ul>\${ohneMess.map(st => \`<li>\${esc(st.titel)}</li>\`).join('')}</ul></details></div>\`;
  };

  // Worum es geht
  bereich('start');
  s.push(\`<section class="worum">
    \${E ? \`<div class="karte \${E.entscheidung === 'freigegeben' ? 'ok' : ''}"><b>Entschieden am \${zeit(E.zeitpunkt)}: \${esc(ENTSCHIEDEN[E.entscheidung] || E.entscheidung)}</b>
      <div>von \${esc(E.person || '–')}\${E.begruendung ? ' · ' + esc(E.begruendung) : ''}</div>
      <div class="hilft">Diese Seite bleibt bis zur Frist zum Nachlesen offen. Eine zweite Entscheidung ist nicht möglich.</div></div>\` : ''}
    <h2>Worum es geht</h2>
    <p>BC3 hat das Konzept \${esc(L.kp_id || '')} von BC2\${ein.unternehmen ? ' für ' + esc(ein.unternehmen) : ''} in \${L.epics.length} Epics mit \${stories} Stories zerlegt,
      rechtlich eingeordnet und abgelegt. \${E ? '' : '<b>Du entscheidest, ob diese Lieferung an BC4 geht.</b> Schau dir dafür vor allem die offenen Punkte und die drei Akzeptanzkriterien an.'}</p>
    \${leiste(!!E)}
    <div class="kopf">
      <div><span>Lauf</span>\${esc(L.lauf_nr)}</div>
      <div><span>Lieferung</span>\${esc(L.lieferung_id)}</div>
      <div><span>Kernprozess</span>\${esc(L.kp_id)}\${L.teilprozesse.length ? ', ' + esc(L.teilprozesse.join(', ')) : ''}</div>
      <div><span>Vertrag</span>\${esc(L.schema_version)}\${L.pruefung_bc3.ergebnis ? ' · ' + esc(L.pruefung_bc3.ergebnis) : ''}</div>
      <div><span>Einstufung</span>\${einstufungTags()}</div>
    </div>
    \${L.hochrisiko ? \`<p class="hinweis">Hochrisiko erkannt über: \${esc(L.hochrisiko_quelle)}.</p>\` : ''}
    <details><summary>Begriffe auf dieser Seite</summary><ul class="begriffe">
      <li><b>Gate 2</b>: die menschliche Freigabe, bevor BC3 an BC4 liefert.</li>
      <li><b>Epic, Story</b>: ein Epic je Potenzial von BC2, darin Stories mit Akzeptanzkriterien, die BC4 baut.</li>
      <li><b>A, K, V</b>: fachliche Anforderung (A1 …) und Akzeptanzkriterium (K1 …) aus dem Konzept von BC2, Vorgabe von BC3 (V1 …).</li>
      <li><b>Abdeckung</b>: ob jede dieser Nummern in einer Story steckt.</li>
      <li><b>Akzeptanzkriterium, Messverfahren</b>: das Kriterium sagt, was erfüllt sein muss („Eine Anfrage über dem Budget geht an die Teamleitung“),
        das Messverfahren, woran man das prüft („im Vorgangsprotokoll den Status ansehen“). BC2 liefert Messverfahren nur zu den K-Nummern,
