      \${L.aufsicht.map(f => \`<div class="karte\${f.stories.length ? ' ok' : ''}"><b>\${esc(f.titel)}</b>
        <div>\${f.stories.length ? 'Belegt durch: ' + esc(f.stories.join('; ')) : 'Keine Story gefunden.'}</div></div>\`).join('')}
      \${E ? '' : \`<div class="wahl" data-feld="aufsicht">\${AUFS_WAHL.map(w => knopf('aufsicht', w)).join('')}</div>\`}
