      <div class="wahl entscheidung" data-feld="entscheidung">\${Object.entries(ENTSCHEIDUNG).map(([k, e]) =>
        \`<button type="button" class="\${e.klasse}\${Z.entscheidung === k ? ' an' : ''}" data-wert="\${k}">\${e.text}</button>\`).join('')}</div>
      \${Z.entscheidung === 'frei' && offen.length ? \`<div class="karte"><b>Du gibst trotz \${offen.length === 1 ? 'eines offenen Punkts' : offen.length + ' offener Punkte'} frei.</b>
        <div class="hilft">Das ist erlaubt. Schreib bitte in die Begründung, warum.</div></div>\` : ''}
      <label for="begruendung">Begründung\${['nach', 'ab'].includes(Z.entscheidung) ? ' (Pflicht)' : ''}</label>
      <textarea id="begruendung" placeholder="Bei Nachbessern und Ablehnen: was soll BC3 tun?">\${esc(Z.begruendung)}</textarea>
      <label for="person">Wer entscheidet</label>
      <input type="text" id="person" value="\${esc(Z.person)}" placeholder="Kürzel">
      <p class="hinweis">Das Namensfeld ist nicht geprüft und belegt keine Vier-Augen-Kontrolle.</p>
      <div class="fehler" id="fehler">\${esc(Z.fehler || '')}</div>
      <button class="btn" id="absenden" \${Z.fertig || Z.sendet ? 'disabled' : ''}>\${Z.sendet ? 'Wird gesendet …' : 'Entscheidung absenden'}</button>
      \${Z.fertig ? \`<div class="karte ok"><b>\${esc(Z.fertig)}</b></div>\` : ''}
