  // --- Seitenleiste -------------------------------------------------------
  const zahl = (n, farbe) => '<span class="tag ' + (farbe || '') + '">' + n + '</span>';
  const NAVI = [
    ['start', 'Start', offen.length ? zahl(offen.length + ' offen', 'rot') : zahl('nichts offen', 'gruen')],
    ['bc2', '1 Von BC2', zahl(pot.length)],
    ['lauf', '2 Lauf', zahl(befunde + ' Befunde')],
    ['ergebnis', '3 Ergebnis', zahl(stories + ' Stories')],
    ['raus', '4 Was rausgeht', zahl((aus.dateien || []).length)],
    ['entscheiden', '5 Entscheiden', E ? zahl(ENTSCHIEDEN[E.entscheidung] || E.entscheidung, E.entscheidung === 'freigegeben' ? 'gruen' : 'gelb')
