  const id = B[location.hash.slice(1)] ? location.hash.slice(1) : 'start';
  // Am Ende jedes Bereichs ein Weiter zum nächsten, so lässt sich die Seite der Reihe nach durchgehen
  const pos = NAVI.findIndex(([k]) => k === id);
  if (pos < NAVI.length - 1) B[id].push('<p><a class="weiter" href="#' + NAVI[pos + 1][0] + '">Weiter: ' + NAVI[pos + 1][1] + '</a></p>');
  document.getElementById('navi').innerHTML = NAVI.map(([k, name, z]) =>
    '<a href="#' + k + '"' + (k === id ? ' class="aktiv"' : '') + '><span>' + name + '</span>' + z + '</a>').join('');
  document.getElementById('seite').innerHTML = B[id].join('');
  if (!E && id === 'entscheiden') binden();
}

// Messverfahren fehlt: leer oder von BC3 als "offen: …" markiert
function fehltMess(m) { return !m || /^offen:/i.test(String(m)); }
function messText(m) { return fehltMess(m) ? 'fehlt (BC2 nennt keins)' : String(m); }

// Laufleiste wie auf der Übersicht BC3-82: bis Gate 2 erledigt, Gate 2 jetzt oder entschieden
function leiste(entschieden) {
  return '<div class="leiste" title="' + esc(SCHRITTE.join(' · ')) + '">' + SCHRITTE.map((x, i) => {
    const k = x === 'Gate 2' ? (entschieden ? 'ja' : 'jetzt') : (i < SCHRITTE.indexOf('Gate 2') ? 'ja' : '');
    return '<span class="' + k + '">' + esc(x) + '</span>';
  }).join('') + '</div>';
}

// Seit 23.10.2026 (C3): auf welchen Artikel der KI-Verordnung sich die Klasse stützt. Feste Liste, kein Modell.
// Die Ampel ist eine eigene Einordnung von BC3 (KI-VO und DSGVO zusammen), keine Kategorie des Gesetzes.
function rechtsgrundlage() {
  const e = L.einstufung || {};
  const anhang = e.anhang_iii_kategorie ? ' (' + e.anhang_iii_kategorie + ')' : '';
  return {
    unacceptable: 'Grundlage: Art. 5 KI-VO, verbotene Praktik. So darf das System nicht gebaut werden, die Pflichten nennen die zulässige Bauweise.',
    high: 'Grundlage: Art. 6 Abs. 2 KI-VO mit Anhang III' + anhang + '. Daraus folgen die Pflichten nach Art. 9 bis 15 '
      + '(Risikomanagement, Daten, Dokumentation, Protokollierung, Transparenz, menschliche Aufsicht, Genauigkeit), '
      + 'für den Betrieb Art. 26. Ob die Ausnahme nach Art. 6 Abs. 3 greift, entscheidet ein Mensch.',
    limited: 'Grundlage: Art. 50 KI-VO, Transparenzpflichten, etwa der Hinweis, dass man mit einer KI zu tun hat, '
      + 'oder die Kennzeichnung erzeugter Inhalte.',
    minimal: 'Grundlage: keine besonderen Pflichten nach der KI-Verordnung. Es gilt nur Art. 4 (KI-Kompetenz der Beschäftigten). '
      + 'Pflichten aus der DSGVO stehen unten.',
  }[e.ai_act_klasse] || 'Grundlage: keine Klasse angegeben.';
}

function einstufungTags() {
  const e = L.einstufung || {};
  const farbe = { green: 'gruen', yellow: 'gelb', red: 'rot' }[e.ampel] || '';
  const ampel = { green: 'grün', yellow: 'gelb', red: 'rot' }[e.ampel] || e.ampel;
  const klasse = { high: 'Hochrisiko', limited: 'begrenztes Risiko', minimal: 'minimales Risiko',
    unacceptable: 'verboten (Art. 5)' }[e.ai_act_klasse] || e.ai_act_klasse;
  return [e.ampel ? \`<span class="tag \${farbe}">Ampel \${esc(ampel)}</span>\` : '',
    e.ai_act_klasse ? \`<span class="tag">\${esc(klasse)}</span>\` : '',
    e.anhang_iii_kategorie ? \`<span class="tag rot">\${esc(e.anhang_iii_kategorie)}</span>\` : ''].join('') || 'ohne Angabe';
}

function knopf(feld, wert) {
  return \`<button type="button" class="\${Z[feld] === wert ? 'an' : ''}" data-wert="\${esc(wert)}">\${esc(wert)}</button>\`;
}

function binden() {
  document.querySelectorAll('.wahl button').forEach(b => b.onclick = () => {
    if (Z.fertig || Z.sendet) return;
    Z[b.parentElement.dataset.feld] = b.dataset.wert;
    Z.fehler = '';
    merken(); zeichnen();
  });
  document.getElementById('begruendung').oninput = e => { Z.begruendung = e.target.value; };
  document.getElementById('person').oninput = e => { Z.person = e.target.value; };
  document.getElementById('absenden').onclick = absenden;
}

function merken() {
  Z.begruendung = document.getElementById('begruendung')?.value ?? Z.begruendung;
  Z.person = document.getElementById('person')?.value ?? Z.person;
}

// Dieselben Prüfungen macht BC3-81 auf dem Server noch einmal
async function absenden() {
  merken();
  const f = [];
  if (!Z.entscheidung) f.push('Bitte eine Entscheidung wählen.');
  if (['nach', 'ab'].includes(Z.entscheidung) && !Z.begruendung.trim()) f.push('Bei Nachbessern und Ablehnen ist die Begründung Pflicht.');
  if (!Z.person.trim()) f.push('Bitte angeben, wer entscheidet.');
  if (!Z.kriterien) f.push('Bitte zu den Akzeptanzkriterien Stellung nehmen.');
  if (L.hochrisiko && !Z.aufsicht) f.push('Bitte zur menschlichen Aufsicht Stellung nehmen.');
  Z.fehler = f.join(' ');
  if (f.length) { zeichnen(); return; }

  Z.sendet = true; zeichnen();
  try {
    const r = await fetch(location.pathname, {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ lauf: ZUGANG.get('lauf'), t: ZUGANG.get('t'), entscheidung: Z.entscheidung,
        kriterien: Z.kriterien, aufsicht: Z.aufsicht, begruendung: Z.begruendung.trim(), person: Z.person.trim() }),
    });
    const a = await r.json().catch(() => ({}));
    if (r.ok && a.ok) Z.fertig = a.meldung || 'Entscheidung gespeichert.';
    else Z.fehler = a.meldung || \`Nicht gespeichert (Fehler \${r.status}).\`;
  } catch (e) {
    Z.fehler = 'Keine Verbindung zum Server. Bitte noch einmal absenden.';
  }
  Z.sendet = false;
  zeichnen();
}

zeigen();
</script>
</body>
</html>
`;

